'use strict';
const APPEARANCE_FONTS={system:{name:'KainCheck default',family:'Inter, "Segoe UI", Arial, sans-serif'},andy:{name:'Andy Bold',family:'"KainCheck Andy", "Segoe UI", sans-serif'},vcr:{name:'VCR OSD Mono',family:'"KainCheck VCR", "Courier New", monospace'},bebas:{name:'Bebas Neue',family:'"KainCheck Bebas", "Arial Narrow", sans-serif'},eva:{name:'EVA Matisse',family:'"KainCheck EVA", Georgia, serif'}};
const APPEARANCE_BACKGROUNDS={none:{name:'Solid color',url:''},terraria:{name:'Terraria Overworld',url:'theme-assets/terraria-overworld.webp'},earthmover:{name:'Earthmover',url:'theme-assets/earthmover.webp'}};
const APPEARANCE_PRESETS={kaincheck:{name:'KainCheck Original',description:'Fresh greens & warm paper',font:'system',background:'none',tint:'#faf9f3',accent:'#174f42',mode:'light',dim:0,opacity:97},terraria:{name:'Terraria Overworld',description:'Andy Bold · sky & floating islands',font:'andy',background:'terraria',tint:'#91b7df',accent:'#315d3f',mode:'light',dim:12,opacity:93},earthmover:{name:'Earthmover',description:'VCR OSD Mono · steel & sunflowers',font:'vcr',background:'earthmover',tint:'#252b2c',accent:'#e6c85a',mode:'dark',dim:37,opacity:93},eva:{name:'EVA Signal',description:'EVA Matisse · violet & amber',font:'eva',background:'none',tint:'#251c31',accent:'#b782eb',mode:'dark',dim:0,opacity:96},sand:{name:'Warm Poster',description:'Bebas Neue · sand & terracotta',font:'bebas',background:'none',tint:'#eddfca',accent:'#914a34',mode:'light',dim:0,opacity:97},midnight:{name:'Midnight Garden',description:'Quiet dark tones & soft mint',font:'system',background:'none',tint:'#142521',accent:'#a4d9b3',mode:'dark',dim:0,opacity:96}};
let appearanceDraft=null,appearanceEpoch=0;
function validAppearanceImage(value){return typeof value==='string'&&value.length<=650000&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(value);}
function normalizeAppearance(raw={}){if(!raw||typeof raw!=='object')raw={};const preset=Object.hasOwn(APPEARANCE_PRESETS,raw.preset)?raw.preset:'kaincheck',p=APPEARANCE_PRESETS[preset],hex=(v,f)=>typeof v==='string'&&/^#[a-f\d]{6}$/i.test(v)?v:f;let background=Object.hasOwn(APPEARANCE_BACKGROUNDS,raw.background)||raw.background==='uploaded'?raw.background:p.background;const image=validAppearanceImage(raw.image)?raw.image:'';if(background==='uploaded'&&!image)background='none';return {preset,font:Object.hasOwn(APPEARANCE_FONTS,raw.font)?raw.font:p.font,background,image,tint:hex(raw.tint,p.tint),accent:hex(raw.accent,p.accent),mode:['light','dark'].includes(raw.mode)?raw.mode:p.mode,dim:boundedNumber(raw.dim,0,80,p.dim),opacity:boundedNumber(raw.opacity,70,100,p.opacity),position:['center','top','bottom'].includes(raw.position)?raw.position:'center'};}
function appearanceRgb(hex){return [1,3,5].map(i=>parseInt(hex.slice(i,i+2),16));}
function appearanceMix(a,b,weight){return '#'+appearanceRgb(a).map((v,i)=>Math.round(v*(1-weight)+appearanceRgb(b)[i]*weight).toString(16).padStart(2,'0')).join('');}
function appearanceLuminance(hex){return appearanceRgb(hex).map(v=>{const n=v/255;return n<=.04045?n/12.92:((n+.055)/1.055)**2.4;}).reduce((sum,v,i)=>sum+v*[.2126,.7152,.0722][i],0);}
function appearanceContrast(a,b){const x=appearanceLuminance(a),y=appearanceLuminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
function appearanceReadableAccent(accent,paper,dark){let color=accent;for(let i=0;i<18&&appearanceContrast(color,paper)<4.5;i++)color=appearanceMix(color,dark?'#ffffff':'#000000',.12);return color;}
function appearanceImageUrl(a){return a.background==='uploaded'?a.image:APPEARANCE_BACKGROUNDS[a.background]?.url||'';}
function applyAppearance(value){const a=normalizeAppearance(value),root=document.documentElement,dark=a.mode==='dark',paper=appearanceMix(a.tint,dark?'#14171a':'#fffef9',dark?.5:.86),surface=appearanceMix(paper,dark?'#272d30':'#ffffff',.25),ink=dark?'#f2f2e8':'#24362d',muted=dark?'#c2c9c5':'#5c6c60',onAccent=appearanceContrast(a.accent,'#ffffff')>appearanceContrast(a.accent,'#141a16')?'#ffffff':'#141a16',rgb=appearanceRgb(surface).join(','),image=appearanceImageUrl(a),font=APPEARANCE_FONTS[a.font].family;
 root.dataset.uiTheme=a.preset;root.dataset.uiMode=a.mode;root.dataset.uiFont=a.font;root.dataset.uiBackground=image?'image':'solid';
 const vars={'--app-font':font,'--heading-font':a.font==='system'?'Georgia, "Times New Roman", serif':font,'--canvas-tone':a.tint,'--pine':a.accent,'--deep':appearanceMix(a.accent,'#000000',.13),'--green':appearanceReadableAccent(a.accent,paper,dark),'--paper':paper,'--white':`rgba(${rgb},${a.opacity/100})`,'--surface-solid':surface,'--surface-muted':appearanceMix(surface,dark?'#3b4641':'#dfe8d5',.26),'--nav-surface':`rgba(${rgb},${Math.max(.94,a.opacity/100)})`,'--ink':ink,'--muted':muted,'--line':appearanceMix(paper,dark?'#f0f5eb':'#31583c',dark?.2:.17),'--mint':appearanceMix(paper,a.accent,dark?.22:.12),'--yellow':a.preset==='eva'?'#ffb85b':'#efcf72','--lav':appearanceMix(paper,'#a98ad9',.18),'--on-accent':onAccent,'--accent-muted':appearanceMix(onAccent,a.accent,.2),'--theme-background':image?`url("${image}")`:'none','--background-shade':`rgba(0,0,0,${a.dim/100})`,'--background-position':a.position==='center'?'center center':'center '+a.position};for(const [key,v] of Object.entries(vars))root.style.setProperty(key,v);root.style.colorScheme=a.mode;return a;}
function applyCurrentAppearance(){applyAppearance(appearanceDraft&&activeModal==='appearance'?appearanceDraft:state.appearance);}
function openAppearance(){appearanceEpoch++;appearanceDraft=normalizeAppearance(state.appearance);appearanceModal();}
function appearancePresetCard(id,p){const bg=APPEARANCE_BACKGROUNDS[p.background]?.url;return `<button type="button" class="appearance-preset ${appearanceDraft.preset===id?'selected':''}" data-appearance-preset="${id}" aria-pressed="${appearanceDraft.preset===id}"><span class="appearance-preset-art" style="background-color:${p.tint};${bg?`background-image:url('${bg}')`:''};color:${p.mode==='dark'?'#f8f5ec':'#1c382d'};font-family:${esc(APPEARANCE_FONTS[p.font].family)}"><i style="background:${p.accent}"></i><b>Aa</b></span><strong>${p.name}</strong><small>${p.description}</small></button>`;}
function appearanceModal(){const a=appearanceDraft;if(!a)return;showModal('Make KainCheck yours',`<p class="subtle">Choose a preset, then tweak the colors, font and background. Preview changes before saving.</p><h3 class="appearance-section-title">Preset themes</h3><div class="appearance-presets">${Object.entries(APPEARANCE_PRESETS).map(([id,p])=>appearancePresetCard(id,p)).join('')}</div><form id="appearance-form"><div class="field-row"><label class="field"><span>Background color tone</span><input id="appearance-tint" type="color" value="${a.tint}"></label><label class="field"><span>Accent color</span><input id="appearance-accent" type="color" value="${a.accent}"></label></div><div class="field-row"><label class="field"><span>Font</span><select id="appearance-font">${Object.entries(APPEARANCE_FONTS).map(([key,f])=>`<option value="${key}" ${a.font===key?'selected':''}>${f.name}</option>`).join('')}</select></label><label class="field"><span>Panel style</span><select id="appearance-mode"><option value="light" ${a.mode==='light'?'selected':''}>Light</option><option value="dark" ${a.mode==='dark'?'selected':''}>Dark</option></select></label></div><h3 class="appearance-section-title">Background picture</h3><label class="field"><span>Picture</span><select id="appearance-background">${Object.entries(APPEARANCE_BACKGROUNDS).map(([key,b])=>`<option value="${key}" ${a.background===key?'selected':''}>${b.name}</option>`).join('')}${a.image?`<option value="uploaded" ${a.background==='uploaded'?'selected':''}>My uploaded picture</option>`:''}</select></label><div class="appearance-upload-row"><label class="secondary appearance-upload-label" for="appearance-picture-file">${ic('plus')}Upload my background</label><input type="file" id="appearance-picture-file" accept="image/png,image/jpeg,image/webp" hidden>${a.image?'<button type="button" class="text-btn danger-text" data-action="remove-theme-picture">Remove my picture</button>':''}</div><p class="field-help">PNG, JPEG or WebP · up to 10 MB. Your image is resized for the app and saved with your preferences. It is not sent to the AI coach.</p><div class="appearance-picture-preview ${appearanceImageUrl(a)?'has-picture':''}" style="background-color:${a.tint};${appearanceImageUrl(a)?`background-image:linear-gradient(${`rgba(0,0,0,${a.dim/100})`},${`rgba(0,0,0,${a.dim/100})`}),url('${appearanceImageUrl(a)}');background-position:center ${a.position};`:''}"><span>${appearanceImageUrl(a)?'Your background preview':'Solid color background'}</span></div><label class="field"><span>Picture position</span><select id="appearance-position">${['top','center','bottom'].map(x=>`<option value="${x}" ${a.position===x?'selected':''}>${x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select></label><label class="field appearance-range"><span>Picture dimming <output id="appearance-dim-value">${a.dim}%</output></span><input id="appearance-dim" type="range" min="0" max="80" value="${a.dim}"><small class="field-help">Darken the picture without changing your original image.</small></label><label class="field appearance-range"><span>Panel opacity <output id="appearance-opacity-value">${a.opacity}%</output></span><input id="appearance-opacity" type="range" min="70" max="100" value="${a.opacity}"><small class="field-help">Higher opacity makes text easier to read over a picture.</small></label><div class="appearance-live-sample"><small>LIVE STYLE PREVIEW</small><h3>Your day, your world.</h3><p>Kumusta! A little food, movement and good company.</p><span class="appearance-sample-chip">Your selected font & colors</span></div><div class="sheet-actions appearance-save-actions"><button class="secondary" type="button" data-action="cancel-appearance">Cancel</button><button class="primary" type="submit">Save appearance</button></div><button type="button" class="text-btn appearance-reset" data-action="reset-appearance">Reset to KainCheck Original</button></form>`);activeModal='appearance';applyAppearance(a);}
function refreshAppearanceDraft(){if(!appearanceDraft||!$('#appearance-form'))return;for(const [key,id] of Object.entries({tint:'tint',accent:'accent',font:'font',mode:'mode',background:'background',dim:'dim',opacity:'opacity',position:'position'}))appearanceDraft[key]=$('#appearance-'+id).value;appearanceDraft=normalizeAppearance(appearanceDraft);applyAppearance(appearanceDraft);$('#appearance-dim-value').textContent=appearanceDraft.dim+'%';$('#appearance-opacity-value').textContent=appearanceDraft.opacity+'%';const preview=$('.appearance-picture-preview');preview.style.backgroundColor=appearanceDraft.tint;preview.style.backgroundImage=appearanceImageUrl(appearanceDraft)?`linear-gradient(rgba(0,0,0,${appearanceDraft.dim/100}),rgba(0,0,0,${appearanceDraft.dim/100})),url("${appearanceImageUrl(appearanceDraft)}")`:'none';preview.style.backgroundPosition='center '+appearanceDraft.position;}
async function uploadAppearancePicture(file){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('Choose a PNG, JPEG or WebP image up to 10 MB.');return;}const epoch=appearanceEpoch,account=accountOperation,submit=$('#appearance-form button[type=submit]');if(submit)submit.disabled=true;toast('Preparing your background…');try{const raw=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);}),image=await new Promise((resolve,reject)=>{const picture=new Image();picture.onload=()=>resolve(picture);picture.onerror=reject;picture.src=raw;});if(epoch!==appearanceEpoch||account!==accountOperation||activeModal!=='appearance'||!appearanceDraft)return;const scale=Math.min(1,1600/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle=appearanceDraft.tint;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);let result;for(const quality of [.82,.65,.48,.32]){result=canvas.toDataURL('image/jpeg',quality);if(validAppearanceImage(result))break;}if(!validAppearanceImage(result))throw Error('Too detailed');refreshAppearanceDraft();appearanceDraft.image=result;appearanceDraft.background='uploaded';appearanceModal();toast('Background ready. Save appearance to keep it.');}catch{toast('Could not use that picture. Try a smaller image.');}finally{if(submit?.isConnected)submit.disabled=false;}}
function installAppearance(){Object.assign(actions,{'appearance':openAppearance,'cancel-appearance':()=>closeModal(),'reset-appearance':()=>{appearanceEpoch++;appearanceDraft=normalizeAppearance({preset:'kaincheck'});appearanceModal();},'remove-theme-picture':()=>{refreshAppearanceDraft();appearanceDraft.image='';if(appearanceDraft.background==='uploaded')appearanceDraft.background='none';appearanceEpoch++;appearanceModal();}});const previousClose=closeModal;closeModal=()=>{if(activeModal==='appearance'){appearanceEpoch++;appearanceDraft=null;applyAppearance(state.appearance);}previousClose();};const baseProfile=profile;profile=()=>baseProfile().replace('<button class="settings-row"',`<button class="settings-row appearance-profile-link" data-action="appearance">${ic('spark')}<span><strong>Appearance & themes</strong><small>Backgrounds, colors & your favorite fonts</small></span>${ic('arrow')}</button><button class="settings-row"`);document.addEventListener('click',e=>{const preset=e.target.closest('[data-appearance-preset]');if(preset&&appearanceDraft){appearanceEpoch++;appearanceDraft=normalizeAppearance({preset:preset.dataset.appearancePreset,image:appearanceDraft.image});appearanceModal();}});document.addEventListener('input',e=>{if(e.target.closest('#appearance-form')&&e.target.id!=='appearance-picture-file')refreshAppearanceDraft();});document.addEventListener('change',e=>{if(e.target.id==='appearance-picture-file')uploadAppearancePicture(e.target.files?.[0]);else if(e.target.closest('#appearance-form'))refreshAppearanceDraft();});document.addEventListener('submit',e=>{if(e.target.id!=='appearance-form')return;e.preventDefault();refreshAppearanceDraft();state.appearance=normalizeAppearance(appearanceDraft);save();appearanceDraft=null;closeModal();render(true);toast('Your appearance is saved.');});applyCurrentAppearance();}
